using namespace std;

int main() {
    string P, A;
    cin >> P >> A;

    vector<int> cnt(26, 0);
    for (char c : P) {
        cnt[c - 'a']++;
    }

    for (char c : A) {
        if (c != '*') {
            int idx = c - 'a';
            cnt[idx]--;
            if (cnt[idx] < 0) {
                cout << 'N' << '\n';
